class DataStore:
    def __init__(self):
        self.users = {}
        self.posts = []
        self.comments = []
        self.messages = []
        self.notifications = []
        self.load_data()

    def load_data(self):
        """从文件加载数据"""
        try:
            if os.path.exists('data/users.json'):
                with open('data/users.json', 'r', encoding='utf-8') as f:
                    self.users = json.load(f)
            if os.path.exists('data/posts.json'):
                with open('data/posts.json', 'r', encoding='utf-8') as f:
                    self.posts = json.load(f)
            if os.path.exists('data/comments.json'):
                with open('data/comments.json', 'r', encoding='utf-8') as f:
                    self.comments = json.load(f)
            if os.path.exists('data/messages.json'):
                with open('data/messages.json', 'r', encoding='utf-8') as f:
                    self.messages = json.load(f)
            if os.path.exists('data/notifications.json'):
                with open('data/notifications.json', 'r', encoding='utf-8') as f:
                    self.notifications = json.load(f)
        except Exception as e:
            print(f"加载数据失败: {e}")

    def save_data(self):
        """保存数据到文件"""
        try:
            os.makedirs('data', exist_ok=True)
            with open('data/users.json', 'w', encoding='utf-8') as f:
                json.dump(self.users, f, ensure_ascii=False, indent=2)
            with open('data/posts.json', 'w', encoding='utf-8') as f:
                json.dump(self.posts, f, ensure_ascii=False, indent=2)
            with open('data/comments.json', 'w', encoding='utf-8') as f:
                json.dump(self.comments, f, ensure_ascii=False, indent=2)
            with open('data/messages.json', 'w', encoding='utf-8') as f:
